/**
 * Renders the fixed-size brand PNGs that need a stable URL: the two web-app
 * manifest icons, a maskable one for Android, and the square logo a search
 * engine asks an organisation for.
 *
 * Everything else (the tab icon, the home-screen icon, the share cards) is
 * generated by Next at build time from the same paths. These four are written
 * to /public and committed, because a manifest and a schema.org `logo` both
 * need a URL that does not change between deploys.
 *
 *   node scripts/build-brand-assets.mjs
 *
 * Re-run it if the mark in src/lib/brand.ts ever changes.
 */
import { mkdir, writeFile } from "node:fs/promises";
import { ImageResponse } from "next/og.js";

const PAPER = "#FBF4E7";
const BLOOM_INK = "#A8492F";

/* Duplicated from src/lib/brand.ts, which is TypeScript this plain script
   cannot import. The check at the bottom fails the run if they drift. */
const VIEWBOX = "0 0 1219 1330";
const PATHS = [
  "M685.814 557.212C761.56 339.828 1000.58 226.514 1216.82 305.477L1120.16 556.408C1040.61 762.947 811.521 869.102 602.515 796.275L685.814 557.212Z",
  "M603.531 511.256C676.062 303.096 566.113 75.5499 357.953 3.01826L268.231 260.513C195.7 468.673 305.648 696.219 513.809 768.751L603.531 511.256Z",
  "M529.234 1000.25C493.009 1104.21 547.922 1217.86 651.885 1254.08L658.885 1256.52C759.15 1291.46 868.731 1238.36 903.442 1138.02C938.043 1037.99 885.147 928.834 785.2 894.008L589.958 825.978L529.234 1000.25Z",
  "M442.498 973.413C406.272 1077.38 292.627 1132.29 188.664 1096.06L181.664 1093.62C81.3988 1058.69 28.5442 948.989 63.7058 848.802C98.7559 748.934 208.032 696.283 307.979 731.109L503.222 799.14L442.498 973.413Z",
  "M643.811 490.412C645.206 483.9 651.615 479.753 658.127 481.148C664.638 482.544 668.786 488.953 667.391 495.464C639.548 625.395 554.638 838.808 484.635 1014.65C449.057 1104.02 400.093 1181.85 351.043 1237.54C326.526 1265.38 301.764 1287.93 278.386 1303.63C255.266 1319.15 232.282 1328.78 211.595 1328.78C204.936 1328.78 199.537 1323.38 199.537 1316.72C199.537 1310.06 204.935 1304.66 211.595 1304.66C225.313 1304.66 243.487 1298.01 264.944 1283.61C286.144 1269.37 309.379 1248.36 332.946 1221.6C380.064 1168.11 427.615 1092.68 462.229 1005.73C532.611 828.937 616.502 617.852 643.811 490.412Z",
];

const markUri = (color) =>
  "data:image/svg+xml;base64," +
  Buffer.from(
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${VIEWBOX}">` +
      PATHS.map((d) => `<path fill="${color}" d="${d}"/>`).join("") +
      "</svg>",
  ).toString("base64");

/** `inset` is the fraction of the square the mark is allowed to occupy. */
async function squarePng(size, inset) {
  const h = Math.round(size * inset);
  const w = Math.round((h * 1219) / 1330);
  const png = await new ImageResponse(
    {
      type: "div",
      props: {
        style: {
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          background: PAPER,
        },
        children: {
          type: "img",
          props: { src: markUri(BLOOM_INK), width: w, height: h },
        },
      },
    },
    { width: size, height: size },
  ).arrayBuffer();
  return Buffer.from(png);
}

async function square(size, inset, file) {
  await writeFile(file, await squarePng(size, inset));
  console.log(`  ${size}×${size}  ${file.pathname.split("/").pop()}`);
}

/**
 * An .ico, assembled by hand.
 *
 * Not vanity: `favicon.ico` still outranks every other icon in most browsers'
 * fallback order, and a handful of link-preview crawlers ask for it by path
 * whether or not the page declares one. Modern .ico may hold PNG payloads
 * directly, which is all this does — a six-byte header, one sixteen-byte
 * directory entry per size, then the PNGs.
 */
async function ico(sizes, file) {
  const images = [];
  for (const size of sizes) {
    // Smaller stamps get less margin, or the mark vanishes at 16px.
    images.push({ size, png: await squarePng(size, size <= 32 ? 0.74 : 0.66) });
  }

  const header = Buffer.alloc(6);
  header.writeUInt16LE(0, 0); // reserved
  header.writeUInt16LE(1, 2); // 1 = icon
  header.writeUInt16LE(images.length, 4);

  let offset = 6 + images.length * 16;
  const entries = images.map(({ size, png }) => {
    const entry = Buffer.alloc(16);
    entry.writeUInt8(size >= 256 ? 0 : size, 0); // width  (0 means 256)
    entry.writeUInt8(size >= 256 ? 0 : size, 1); // height
    entry.writeUInt8(0, 2); // palette size — 0 for truecolour
    entry.writeUInt8(0, 3); // reserved
    entry.writeUInt16LE(1, 4); // colour planes
    entry.writeUInt16LE(32, 6); // bits per pixel
    entry.writeUInt32LE(png.length, 8);
    entry.writeUInt32LE(offset, 12);
    offset += png.length;
    return entry;
  });

  await writeFile(
    file,
    Buffer.concat([header, ...entries, ...images.map((i) => i.png)]),
  );
  console.log(`  ${sizes.join("/")}      ${file.pathname.split("/").pop()}`);
}

await mkdir(new URL("../public/brand/", import.meta.url), { recursive: true });
const out = (name) => new URL(`../public/brand/${name}`, import.meta.url);

await square(192, 0.6, out("icon-192.png"));
await square(512, 0.6, out("icon-512.png"));
/* Maskable: Android crops up to 20% off every edge, so the mark sits inside
   the 80% safe circle and the paper runs to the bleed. */
await square(512, 0.42, out("icon-maskable-512.png"));
/* The logo a search engine reads. Google wants at least 112×112. */
await square(512, 0.62, out("logo.png"));

/* And the one file that does not live in /public: the app directory's own
   favicon, which Next serves at /favicon.ico. */
await ico([16, 32, 48], new URL("../src/app/favicon.ico", import.meta.url));
